settings.custom_css:
selector {
  padding: 160px 48px 100px;
  position: relative;
  overflow: hidden;
  text-align: center;
}

#hero-video {
  position: relative;
}

#hero-video::after {
  content: '';
  position: absolute;
  inset: 0;
  background: rgba(8, 10, 12, 0.2); /* color + opacity */
  pointer-events: none; /* lets clicks through to the play button */
  z-index: 1;
}

selector .watch-signals {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 20px;
}

/* 1. Reset counter on the parent section */
#steps-section {
  counter-reset: box-counter;
}

/* 2. Each icon box increments */
#steps-section .elementor-icon-box-wrapper {
  counter-increment: box-counter;
}

/* 3. Hide the actual icon */
#steps-section .elementor-icon-box-icon i,
#steps-section .elementor-icon-box-icon svg {
  display: none;
}

/* 4. Inject the number in its place */
#steps-section .elementor-icon-box-icon::before {
content: counter(box-counter, decimal-leading-zero);
font-family: 'Syne', sans-serif;

  display: flex;
  align-items: center;
  justify-content: center;
  width: 60px;
    height: 20px;

  color: #00D2B4;
  font-size: 22px;
  font-weight: 700;
  margin: 0 auto;
}

selector .elementor-button[type="submit"] {  background: #00d2b4 !important;
  color: #080a0c !important;
  font-family: 'Syne', sans-serif !important;
  font-size: 13px !important;
  font-weight: 600 !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
  border-radius: 4px !important;
  padding: 13px 28px !important;
  border: none !important;
  transition: opacity 0.2s !important;
}

selector .elementor-button[type="submit"]:hover {  opacity: 0.85 !important; }
